  // Button icons (UI pass): a Bootstrap icon from CVIWA.icons (cvi/app/icons.js, loaded before this file) in
  // a <span class="btn-icon">, before the button's words. iconHtml() gives the markup for buttons a script writes;
  // buttonText() changes a button's words and keeps its icon.
  const iconSvg = name => (root.CVIWA && root.CVIWA.icons && root.CVIWA.icons[name]) || '';
  function iconHtml(name) {
    return '<span class="btn-icon" data-icon="' + name + '" aria-hidden="true">' + iconSvg(name) + '</span>';
  }
  function buttonText(button, text) {
    const icon = button.querySelector('.btn-icon');
    button.textContent = text;
    if (icon) button.prepend(icon);
  }

  // The glossary (UI pass): terms that recur on every page, written once here and shown in each page's footer
  // as a fold, closed at first, in every <div data-wsda-glossary>.
  const GLOSSARY = [
    ['CVI', 'Certificate of Veterinary Inspection: the health certificate a veterinarian issues for animals being ' +
      'moved. Each row of a CVI file is one movement record, and one CVI can cover several rows (for example one ' +
      'per species).'],
    ['Premises', 'A farm, ranch, sale yard or other place where animals are kept or handled (one word for one or ' +
      'many). County Focus draws a circle for each premises; Premise Lookup finds the records near places you enter.'],
    ['WA-to-WA', 'A movement with its origin and its destination both in Washington. It is a departure from one ' +
      'county and an arrival in another, so counts of records, or of arrivals plus departures, include it twice; ' +
      'Total animals counts it once.'],
    ['Bundle', 'A ZIP file or folder holding the data files for one or more dashboards, with an optional ' +
      'bundle.json that names them and gives the preparation date and coverage period. What each dashboard can ' +
      'show depends on the files it is given.'],
    // CH: the shaded maps of the CVI page and the Infrastructure dashboard's Density view.
    ['Shaded map (choropleth)', 'A map that fills each county or state with a color for its value, light for ' +
      'little and dark for much, in a few classes shown in the legend. Big places can look busy only because they ' +
      'are big; a per square mile measure corrects for size.']
  ];
  // The glossary fold: a closed <details> holding the terms as a definition list.
  function glossaryElement(doc) {
    const fold = doc.createElement('details');
    fold.className = 'glossary';
    const summary = doc.createElement('summary');
    summary.textContent = 'Terms used on these pages';
    const list = doc.createElement('dl');
    for (const [term, meaning] of GLOSSARY) {
      const dt = doc.createElement('dt');
      dt.textContent = term;
      const dd = doc.createElement('dd');
      dd.textContent = meaning;
      list.append(dt, dd);
    }
    fold.append(summary, list);
    return fold;
  }

